window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _jn = SLP.books.find(function(b){ return b.id === "john"; });
if (!_jn) throw new Error("data/canon.js must load before nt-03-john.js");
(_jn.chapters = _jn.chapters || []).push(
  { n:1, summary:"John opens before creation: the Word was with God, was God, made all things, and in Him was life and light for the world. John the Baptist came as a witness to that Light, not the Light himself. The Word became flesh and dwelt among us, full of grace and truth; His own received Him not, yet to as many as received Him He gave power to become the sons of God. When priests and Levites from Jerusalem challenged him, the Baptist confessed he was not the Christ but a voice crying in the wilderness, unworthy to loose the Savior's shoe latchet. Seeing the Spirit descend like a dove, he identified Jesus as the Lamb of God and the Son of God. Andrew, Peter, Philip, and Nathanael then followed, one invitation at a time.",
    context:"Traditionally attributed to John the beloved disciple and dated late in the first century, this Gospel opens at Bethabara beyond Jordan, where John bore witness, and in Galilee, where the first disciples followed.",
    keyVerses:[
      { ref:"John 1:1", text:"In the beginning was the Word, and the Word was with God, and the Word was God." },
      { ref:"John 1:14", text:"And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth." },
      { ref:"John 1:29", text:"The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world." }
    ],
    takeaway:"Jesus Christ lived with the Father before the world was and came as the Light and Life of all who will receive Him.",
    quiz:[
      { q:"Whom did Andrew first find to tell, We have found the Messias?", choices:["His own brother Simon","Philip of Bethsaida","Nathanael of Cana","Nicodemus the Pharisee"], a:0, why:"Andrew heard John and followed Jesus, then first found his own brother Simon and brought him to Jesus." },
      { q:"When priests and Levites asked who he was, how did John the Baptist answer?", choices:["I am the Christ","I am Elias","I am the voice of one crying in the wilderness","I am that prophet"], a:2, why:"John confessed, and denied not, that he was not the Christ, not Elias, not that prophet, but a voice crying in the wilderness, as Esaias said." },
      { q:"What did John testify Jesus gives to as many as receive Him?", choices:["Riches for their poverty","Power to become the sons of God","Thrones in Jerusalem","A written law"], a:1, why:"To as many as received Him and believed on His name, He gave power to become the sons of God, born of God." }
    ] },
  { n:2, summary:"Cana's wedding wine ran out, and Mary told her Son simply, They have no wine. Jesus had the six stone waterpots filled with water, and the governor of the feast marveled that the best wine had been kept until now; this beginning of miracles manifested His glory, and His disciples believed on Him. Going up to Jerusalem at Passover, Jesus found merchants and money changers in the temple courts, drove them out with a scourge of small cords, and forbade making His Father's house a house of merchandise. Asked for a sign, He answered, Destroy this temple, and in three days I will raise it up, speaking of the temple of His body; the disciples later understood. At the feast many believed at His miracles, but Jesus did not commit Himself to them, knowing all men.",
    context:"Jesus, His mother, and His disciples attend a wedding in Cana of Galilee, then go up to Jerusalem for the Passover, where Jesus cleanses the temple courts.",
    keyVerses:[
      { ref:"John 2:5", text:"His mother saith unto the servants, Whatsoever he saith unto you, do it." },
      { ref:"John 2:11", text:"This beginning of miracles did Jesus in Cana of Galilee, and manifested forth his glory; and his disciples believed on him." },
      { ref:"John 2:19", text:"Jesus answered and said unto them, Destroy this temple, and in three days I will raise it up." }
    ],
    takeaway:"Simple obedience to whatever the Savior asks is how His power enters ordinary needs.",
    quiz:[
      { q:"How many stone waterpots stood at Cana, set out for Jewish purifying?", choices:["Two","Four","Seven","Six"], a:3, why:"There were set there six waterpots of stone, after the manner of the purifying of the Jews, and Jesus had them filled to the brim." },
      { q:"What did Jesus mean by, Destroy this temple, and in three days I will raise it up?", choices:["He spoke of the temple of His body and His Resurrection","He promised to rebuild Herod's temple quickly","He threatened to destroy the temple courts","He foretold the fall of Jerusalem"], a:0, why:"John explains that Jesus spake of the temple of His body, and the disciples remembered the saying after He was risen from the dead." },
      { q:"What principle does Mary's direction, Whatsoever he saith unto you, do it, teach?", choices:["Miracles require careful planning","Obedience to the Savior's word, however unusual, opens the way for His power","Guests should bring their own wine","Servants should verify instructions with the host"], a:1, why:"The servants did whatever Jesus told them, and the water became wine; His mother pointed them to plain obedience before the miracle." }
    ] },
  { n:3, summary:"Nicodemus, a Pharisee and ruler of the Jews, came to Jesus by night and acknowledged that God was with Him. Jesus answered that no one can see or enter the kingdom of God without being born again, born of water and of the Spirit; fleshly birth alone is not enough, and the Spirit's work is like the wind, felt though unseen. Jesus then testified of heavenly things: as Moses lifted up the serpent, so must the Son of man be lifted up, for God so loved the world that He gave His only begotten Son, not to condemn it but to save it; men loved darkness rather than light. Later, in Judaea, Jesus baptized while John baptized at Aenon, and John rejoiced that Jesus must increase while he must decrease.",
    context:"Jesus speaks by night with Nicodemus, a Pharisee and ruler of the Jews, then baptizes with His disciples in the land of Judaea while John baptizes at Aenon near Salim.",
    keyVerses:[
      { ref:"John 3:5", text:"Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God." },
      { ref:"John 3:16", text:"For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life." },
      { ref:"John 3:17", text:"For God sent not his Son into the world to condemn the world; but that the world through him might be saved." }
    ],
    takeaway:"Entrance into God's kingdom requires a new birth of water and of the Spirit, made possible by God's gift of His Son.",
    quiz:[
      { q:"Nicodemus, the man who came to Jesus by night, held what position?", choices:["A scribe from Galilee","A Roman centurion","A man of the Pharisees and a ruler of the Jews","A Levite of the temple guard"], a:2, why:"John introduces him as a man of the Pharisees, named Nicodemus, a ruler of the Jews." },
      { q:"To what did Jesus compare everyone who is born of the Spirit?", choices:["A lamp on a lampstand","Seed growing quietly","A storm on the sea","The wind that blows where it listeth"], a:3, why:"The wind is heard but its coming and going are unknown; so is every one that is born of the Spirit." },
      { q:"What does John's joy, He must increase, but I must decrease, teach about serving God?", choices:["Faithful servants rejoice in God's work succeeding, even when another receives the following","A ministry should grow steadily larger","Only famous teachers can do God's work","Servants should compete for disciples"], a:0, why:"John called himself the friend of the bridegroom who rejoices greatly at the bridegroom's voice; a man can receive nothing except it be given him from heaven." }
    ] },
  { n:4, summary:"Wearied at Jacob's well near Sychar, Jesus asked a Samaritan woman for a drink and turned the request into an offer of living water that would spring up into everlasting life. He disclosed her history of five husbands, and she perceived He was a prophet; when she spoke of the coming Messias, Jesus told her plainly, I that speak unto thee am he. Leaving her waterpot, she told the men of the city, and many believed; after two days with Him, many more believed because of His own word, confessing Him the Christ, the Saviour of the world. Jesus taught His disciples that His meat was to do the Father's will and that fields were white to harvest. In Cana, He healed a nobleman's dying son with a word, and the whole house believed.",
    context:"Traveling from Judaea into Galilee, Jesus rests at Jacob's well by Sychar in Samaria, teaches a Samaritan woman, stays two days with her people, and heals a nobleman's son in Cana.",
    keyVerses:[
      { ref:"John 4:14", text:"But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life." },
      { ref:"John 4:26", text:"Jesus saith unto her, I that speak unto thee am he." },
      { ref:"John 4:34", text:"Jesus saith unto them, My meat is to do the will of him that sent me, and to finish his work." }
    ],
    takeaway:"Christ gives living water that becomes in us a well springing up into everlasting life; those who hear Him believe for themselves.",
    quiz:[
      { q:"At what landmark did Jesus stop and speak with the Samaritan woman?", choices:["The pool of Bethesda","Jacob's well","The brook Cedron","The fountain of Siloam"], a:1, why:"Jacob's well was near Sychar, and Jesus, wearied with His journey, sat upon it about the sixth hour." },
      { q:"How did the Samaritans' faith in Jesus develop over His two days with them?", choices:["They refused Him until He worked a miracle","They believed only the woman's report","Many first believed her saying, and many more believed because of His own word","They believed after He cleansed their synagogue"], a:2, why:"Many believed because of the woman's testimony, then told her, Now we believe, not because of thy saying: for we have heard him ourselves." },
      { q:"What did Jesus' promise of living water reveal about the satisfaction He gives?", choices:["Well water is purer than city water","Only travelers need such a gift","Worship is tied to one mountain or city","Whoever drinks of His water never thirsts, for it becomes everlasting life within"], a:3, why:"Jesus said whosoever drinketh of the water that I shall give him shall never thirst, a well springing up into everlasting life." }
    ] },
  { n:5, summary:"At the pool of Bethesda in Jerusalem lay a multitude of invalids, among them a man who had suffered thirty and eight years. Jesus asked, Wilt thou be made whole? then commanded him to rise, take up his bed, and walk; the healing fell on the sabbath, and the Jews persecuted Jesus for it and sought to kill Him for calling God His Father, making Himself equal with God. Jesus answered that the Son does what He sees the Father do, that the Father has committed all judgment to the Son so that all should honor the Son, and that those who hear His word pass from death unto life. All in the graves will hear His voice and come forth. He cited John the Baptist, His works, the Father, and the scriptures of Moses as witnesses.",
    context:"At a feast in Jerusalem, Jesus heals an invalid at the pool of Bethesda on the sabbath day, then answers the Jewish leaders who persecute Him for it.",
    keyVerses:[
      { ref:"John 5:8", text:"Jesus saith unto him, Rise, take up thy bed, and walk." },
      { ref:"John 5:24", text:"Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life." },
      { ref:"John 5:39", text:"Search the scriptures; for in them ye think ye have eternal life: and they are they which testify of me." }
    ],
    takeaway:"Jesus acts in the Father's power and judges justly; the scriptures themselves testify of Him, so honor the Son as the Father.",
    quiz:[
      { q:"How long had the man lying at the pool of Bethesda suffered his infirmity?", choices:["Thirty and eight years","Twelve years","Twenty and two years","Forty years"], a:0, why:"A certain man was there which had an infirmity thirty and eight years, and Jesus knew he had been a long time in that case." },
      { q:"Why did the Jews seek to kill Jesus after the healing?", choices:["He refused to keep the Passover","He had healed on the sabbath and said God was His Father, making Himself equal with God","He claimed authority over Rome","He taught in the temple without permission"], a:1, why:"They persecuted Him for doing these things on the sabbath day, and sought the more to kill Him because He called God His Father." },
      { q:"What did Jesus teach about honoring the Son and the Father?", choices:["Only the Father deserves honor","Honor depends on keeping Moses' law alone","The Son refuses all honor","All men should honour the Son even as they honour the Father"], a:3, why:"The Father has committed all judgment to the Son that all men should honour the Son, even as they honour the Father; he that honoureth not the Son honoureth not the Father." }
    ] },
  { n:6, summary:"Beside the sea of Galilee, Jesus fed about five thousand men with five barley loaves and two small fishes; after giving thanks He distributed through the disciples, and twelve baskets of fragments remained. The people wanted to make Him a king by force, so He withdrew; that night He came to His struggling disciples walking on the sea, saying, It is I; be not afraid. Back in Capernaum He redirected their hunger: labour not for meat which perisheth, but believe on Him whom the Father sent. I am the bread of life, He declared, the living bread come down from heaven whose flesh He would give for the life of the world. Many disciples found it a hard saying and left. Peter answered for the twelve: Lord, to whom shall we go? thou hast the words of eternal life.",
    context:"Before the Passover, on a mountain by the sea of Galilee, Jesus feeds about five thousand, walks on the sea toward Capernaum, and teaches in the synagogue there.",
    keyVerses:[
      { ref:"John 6:9", text:"There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?" },
      { ref:"John 6:35", text:"And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst." },
      { ref:"John 6:68", text:"Then Simon Peter answered him, Lord, to whom shall we go? thou hast the words of eternal life." }
    ],
    takeaway:"Jesus is the bread of life; coming to Him and partaking of His sacrifice satisfies hunger the world cannot.",
    quiz:[
      { q:"What food did the lad offer, which Jesus multiplied for the multitude?", choices:["Bread and wine","Seven loaves and three fishes","Five barley loaves and two small fishes","Dried corn and dates"], a:2, why:"Andrew reported a lad with five barley loaves and two small fishes, and asked what they were among so many." },
      { q:"Why did Jesus withdraw alone to a mountain after feeding the five thousand?", choices:["He perceived they would take Him by force to make Him a king","The Roman soldiers were approaching","The disciples begged for rest","The feast of tabernacles began"], a:0, why:"When Jesus perceived that they would come and take him by force, to make him a king, he departed again into a mountain himself alone." },
      { q:"What did Peter's answer, to whom shall we go, teach about following Christ?", choices:["Disciples should follow the crowd","Jesus alone has the words of eternal life, so there is nowhere else to turn","Hard sayings justify leaving","Apostles may choose their own doctrines"], a:1, why:"When many disciples went back, Peter answered for the twelve: thou hast the words of eternal life, and we believe and are sure that thou art that Christ." }
    ] },
  { n:7, summary:"Jesus stayed in Galilee while His unbelieving brothers urged Him to publicize Himself at the feast of tabernacles; He went up privately instead. Midway through the feast He taught in the temple, declaring that His doctrine was the Father's and that anyone willing to do God's will would know whether it was of God. The crowd argued over Him: some called Him a good man, others a deceiver; rulers wondered; none could lay hands on Him because His hour was not yet come. On the last, great day He cried, If any man thirst, let him come unto me and drink, speaking of the Spirit that believers would receive. The people divided over whether He was the Prophet or the Christ, and officers sent to seize Him returned saying, Never man spake like this man.",
    context:"During the feast of tabernacles at Jerusalem, Jesus teaches openly in the temple while the crowds, His skeptical brothers, and the rulers divide over who He is.",
    keyVerses:[
      { ref:"John 7:16", text:"Jesus answered them, and said, My doctrine is not mine, but his that sent me." },
      { ref:"John 7:37", text:"In the last day, that great day of the feast, Jesus stood and cried, saying, If any man thirst, let him come unto me, and drink." },
      { ref:"John 7:46", text:"The officers answered, Never man spake like this man." }
    ],
    takeaway:"Willingness to do God's will is how anyone comes to know whether the doctrine is of God.",
    quiz:[
      { q:"Which feast brought crowds to Jerusalem in this chapter?", choices:["The Passover","The feast of dedication","Pentecost","The feast of tabernacles"], a:3, why:"Now the Jews' feast of tabernacles was at hand, and Jesus' brothers urged Him to go up to Judaea for it." },
      { q:"Why did the officers sent to arrest Jesus come back without Him?", choices:["Jesus had fled to Galilee","The crowds hid Him","They testified, Never man spake like this man","The Pharisees cancelled the order"], a:2, why:"Asked why they had not brought Him, the officers answered, Never man spake like this man." },
      { q:"What test did Jesus give for recognizing doctrine that is of God?", choices:["If any man will do his will, he shall know of the doctrine","Count the size of the teacher's following","Judge by the appearance of miracles","Ask the rulers to vote"], a:0, why:"Jesus said My doctrine is not mine, but his that sent me, and that willingness to do the Father's will reveals whether it is of God." }
    ] },
  { n:8, summary:"Early in the morning at the temple, scribes and Pharisees dragged in a woman taken in adultery, hoping He would speak against the law of Moses. He answered, He that is without sin among you, let him first cast a stone at her; convicted by conscience, her accusers left one by one, and Jesus refused to condemn her, sending her away to sin no more. Then He declared, I am the light of the world, defending His own witness with the Father's. To Jews who believed, He promised that continuing in His word would make them disciples indeed, knowing truth that makes free; whoever commits sin is the servant of sin. The dispute sharpened over lineage and paternity until Jesus bore witness, Before Abraham was, I am, and His hearers took up stones.",
    context:"Early in the morning at the Jerusalem temple, Jesus turns aside the accusers of a woman taken in adultery, then teaches in the treasury as the light of the world.",
    keyVerses:[
      { ref:"John 8:7", text:"So when they continued asking him, he lifted up himself, and said unto them, He that is without sin among you, let him first cast a stone at her." },
      { ref:"John 8:12", text:"Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life." },
      { ref:"John 8:58", text:"Jesus said unto them, Verily, verily, I say unto you, Before Abraham was, I am." }
    ],
    takeaway:"Continuing in Christ's word brings knowledge of truth that frees from sin's bondage; the light exposes, mercy forgives.",
    quiz:[
      { q:"Where was Jesus teaching when He declared, I am the light of the world?", choices:["On the mount of Olives","In the treasury, as He taught in the temple","In Solomon's porch","Beside Jacob's well"], a:1, why:"John notes these words spake Jesus in the treasury, as he taught in the temple, and no man laid hands on Him, for His hour was not yet come." },
      { q:"When Jesus said, Before Abraham was, I am, what was He claiming?", choices:["That Abraham would soon return","That He was older than fifty years","That ancestry alone determines worth","That He is the everlasting God, existing before Abraham"], a:3, why:"His hearers understood Him to make Himself greater than Abraham and took up stones, for He claimed eternal, divine existence." },
      { q:"What chain does Jesus describe between discipleship, truth, and freedom?", choices:["Freedom comes from noble birth","Truth is whatever each person decides","Continuing in His word makes disciples indeed, who know the truth that makes them free","Laws secure liberty for everyone"], a:2, why:"If ye continue in my word, then are ye my disciples indeed; and ye shall know the truth, and the truth shall make you free." }
    ] },
  { n:9, summary:"Seeing a man blind from his birth, Jesus told His disciples that neither the man nor his parents had sinned, but that the works of God should be made manifest in him; then He anointed the man's eyes with clay and sent him to wash in the pool of Siloam, and he came seeing. Because it was the sabbath, the Pharisees investigated, dividing among themselves over whether a sinner could open blind eyes. Questioned repeatedly, the healed man stood by what he knew: whereas I was blind, now I see, and he defended Jesus as a prophet. When the Jews cast him out, Jesus found him, revealed Himself as the Son of God, and the man worshipped Him. Jesus added that He came for judgment, that those who claim to see may be shown blind.",
    context:"In Jerusalem, on the sabbath, Jesus gives sight to a man blind from his birth by anointing his eyes and sending him to wash in the pool of Siloam; the Pharisees investigate.",
    keyVerses:[
      { ref:"John 9:3", text:"Jesus answered, Neither hath this man sinned, nor his parents: but that the works of God should be made manifest in him." },
      { ref:"John 9:5", text:"As long as I am in the world, I am the light of the world." },
      { ref:"John 9:25", text:"He answered and said, Whether he be a sinner or no, I know not: one thing I know, that, whereas I was blind, now I see." }
    ],
    takeaway:"A personal witness, grounded in what Christ has actually done for us, can stand even when it costs us standing.",
    quiz:[
      { q:"Where did Jesus send the man born blind to wash?", choices:["The pool of Siloam","The river Jordan","The pool of Bethesda","The baths of Tiberias"], a:0, why:"Jesus anointed his eyes with clay and said, Go, wash in the pool of Siloam; he went, washed, and came seeing." },
      { q:"Why did the healed man's parents answer the Pharisees so cautiously?", choices:["They doubted the miracle","They were traveling soon","They feared the Jews, who had agreed to put out of the synagogue anyone confessing Christ","They resented their son's healing"], a:2, why:"The parents confirmed he was born blind but said, ask him: for the Jews had agreed that any who confessed Christ should be put out of the synagogue." },
      { q:"What does the healed man's witness, whereas I was blind, now I see, model?", choices:["Debating experts is the best defense","Miracles remove the need for conviction","Only priests may testify of God","A simple, personal testimony of what Christ has done stands firm under pressure"], a:3, why:"Pressed repeatedly, the man answered with what he knew for himself, defended Jesus as a prophet, and worshipped Him when Jesus found him." }
    ] },
  { n:10, summary:"Jesus painted the picture of a sheepfold: the shepherd enters by the door, calls his own sheep by name, and they follow his voice, fleeing strangers. He declared Himself both the door of the sheep and the good shepherd, who gives His life for the sheep while the hireling flees the wolf. He added, other sheep I have, which are not of this fold, promising one fold and one shepherd, and testified that no man takes His life from Him; He lays it down of Himself by His Father's commandment. At the feast of the dedication in Jerusalem the Jews demanded to know plainly whether He was the Christ. His works, He said, bear witness; His sheep hear His voice and none can pluck them from His hand; I and my Father are one. They took up stones, and He escaped beyond Jordan, where many believed.",
    context:"Teaching first the shepherd discourse and then, at the winter feast of the dedication in Jerusalem's temple, Jesus withdraws beyond Jordan when the Jews again seek to stone Him.",
    keyVerses:[
      { ref:"John 10:10", text:"The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly." },
      { ref:"John 10:11", text:"I am the good shepherd: the good shepherd giveth his life for the sheep." },
      { ref:"John 10:16", text:"And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd." }
    ],
    takeaway:"The good Shepherd knows His sheep by name, lays down His life for them, and none can pluck them from His hand.",
    quiz:[
      { q:"Which feast was being observed at Jerusalem when the Jews demanded a plain answer about being the Christ?", choices:["The feast of tabernacles","The feast of the dedication","The Passover","The feast of weeks"], a:1, why:"It was at Jerusalem the feast of the dedication, and it was winter, and Jesus walked in the temple in Solomon's porch." },
      { q:"In the sheepfold figure, what two roles does Jesus claim for Himself?", choices:["The door of the sheep and the good shepherd","The porter and the hireling","The fold and the wolf","The stranger and the watchman"], a:0, why:"Jesus said, I am the door of the sheep and I am the good shepherd, who giveth His life for the sheep." },
      { q:"What did Jesus mean by, other sheep I have, which are not of this fold?", choices:["He would disband Israel's fold","Gentiles would replace the covenant people","Shepherds should enlarge their flocks","He had a people beyond this fold who would hear His voice, until there is one fold and one shepherd"], a:3, why:"Them also I must bring, He said, and they shall hear my voice; and there shall be one fold, and one shepherd." }
    ] },
  { n:11, summary:"When Lazarus of Bethany fell sick, his sisters sent word to Jesus, who said the sickness was for the glory of God, then waited two days before traveling, telling the disciples plainly that Lazarus was dead. Martha met Him with faith that God would give whatever He asked; Jesus told her, I am the resurrection, and the life, and she confessed Him the Christ, the Son of God. At the tomb, Jesus wept with the mourners, then commanded that the stone be taken away and cried, Lazarus, come forth; the dead man came out, bound in graveclothes. Many believed; others reported to the Pharisees, and the council, fearing Rome, heard Caiaphas the high priest argue that one man should die for the people. From that day they plotted His death, and Jesus withdrew to Ephraim.",
    context:"Jesus raises Lazarus at Bethany, a town near Jerusalem, and the council under Caiaphas the high priest resolves from that day to put Him to death.",
    keyVerses:[
      { ref:"John 11:4", text:"When Jesus heard that, he said, This sickness is not unto death, but for the glory of God, that the Son of God might be glorified thereby." },
      { ref:"John 11:25", text:"Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:" },
      { ref:"John 11:43", text:"And when he thus had spoken, he cried with a loud voice, Lazarus, come forth." }
    ],
    takeaway:"Because Jesus is the resurrection and the life, faith in Him turns even death into an occasion for God's glory.",
    quiz:[
      { q:"How long had Lazarus lain in the grave when Jesus reached Bethany?", choices:["Two days","Three days","Four days","Seven days"], a:2, why:"When Jesus came, he found that he had lain in the grave four days already." },
      { q:"Why did Jesus say He was glad He had not been present when Lazarus died?", choices:["To avoid the mourners","Because He feared arrest at Bethany","To spare the sisters embarrassment","For the disciples' sake, to the intent ye may believe"], a:3, why:"Jesus told the disciples He was glad for their sakes that He was not there, that they might believe, and then raised Lazarus." },
      { q:"What does Jesus' declaration, I am the resurrection, and the life, promise the believer?", choices:["An escape from grieving","That though he were dead, yet shall he live","That graves will never be opened","That death ends all ties"], a:1, why:"Jesus told Martha that he that believeth in me, though he were dead, yet shall he live, and asked, Believest thou this?" }
    ] },
  { n:12, summary:"Six days before the Passover, a supper was made for Jesus in Bethany, where Mary anointed His feet with costly spikenard and wiped them with her hair, while Judas Iscariot protested the waste; Jesus defended her, tying the ointment to His burial. The next day He rode into Jerusalem on a young ass as crowds spread palm branches and cried, Hosanna: Blessed is the King of Israel. Certain Greeks asked to see Him, and Jesus announced that the hour was come for the Son of man to be glorified: except a corn of wheat fall into the ground and die, it abideth alone. A voice from heaven confirmed the Father's glory, and Jesus foretold that if He were lifted up, He would draw all men unto Him. Some rulers believed but stayed silent, loving the praise of men more than the praise of God.",
    context:"Six days before the Passover, Jesus is anointed at a Bethany supper, rides into Jerusalem amid palm branches the next day, and teaches the crowd as certain Greeks seek Him.",
    keyVerses:[
      { ref:"John 12:13", text:"Took branches of palm trees, and went forth to meet him, and cried, Hosanna: Blessed is the King of Israel that cometh in the name of the Lord." },
      { ref:"John 12:24", text:"Verily, verily, I say unto you, Except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit." },
      { ref:"John 12:32", text:"And I, if I be lifted up from the earth, will draw all men unto me." }
    ],
    takeaway:"Fruitful disciples lose their life for Christ's sake; His being lifted up draws all men unto Him.",
    quiz:[
      { q:"Who complained that the costly ointment should have been sold for three hundred pence and given to the poor?", choices:["Judas Iscariot","Simon Peter","Thomas Didymus","Andrew"], a:0, why:"Judas Iscariot, Simon's son, which should betray him, objected; John notes he said this not because he cared for the poor, but because he was a thief and had the bag." },
      { q:"When certain Greeks asked to see Jesus, what did He announce?", choices:["That He would avoid Jerusalem","That the hour is come, that the Son of man should be glorified","That only Israel may see Him","That the Greeks should follow Moses"], a:1, why:"The Greeks' request drew the answer, The hour is come, that the Son of man should be glorified, with the parable of the corn of wheat." },
      { q:"What principle lies in the corn of wheat that falls into the ground and dies?", choices:["Good harvests depend on rich soil alone","Grain must be stored against famine","Only by dying does it bring forth much fruit; self-loss for Christ keeps life unto life eternal","Winter ends all growth permanently"], a:2, why:"Jesus taught that except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit, and he that loveth his life shall lose it." }
    ] },
  { n:13, summary:"At the Passover supper, knowing His hour was come and that He should depart unto the Father, Jesus rose, girded Himself with a towel, and washed the disciples' feet, over Peter's protest, giving them an example: if their Lord and Master served so, they ought to wash one another's feet, for the servant is not greater than his lord. Troubled in spirit, He announced that one of them would betray Him and identified Judas with a dipped sop; Judas went out immediately, and it was night. Jesus then spoke of glory: now is the Son of man glorified. He called them little children, told them He was going where they could not yet come, and gave a new commandment, that they love one another as He had loved them, by which all men would know His disciples. Peter's pledge to die for Him drew the warning of a threefold denial.",
    context:"At the Passover supper in Jerusalem, Jesus washes the disciples' feet, identifies Judas as His betrayer, gives a new commandment of love, and warns Peter of a coming denial.",
    keyVerses:[
      { ref:"John 13:5", text:"After that he poureth water into a basin, and began to wash the disciples' feet, and to wipe them with the towel wherewith he was girded." },
      { ref:"John 13:15", text:"For I have given you an example, that ye should do as I have done to you." },
      { ref:"John 13:34", text:"A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another." }
    ],
    takeaway:"Greatness in the Savior's kingdom is measured in humble service, and love for one another is His disciples' mark.",
    quiz:[
      { q:"By what sign did Jesus identify His betrayer to the disciples?", choices:["A name written on a napkin","A nod from Peter","A knock at the door","Giving a dipped sop to Judas Iscariot"], a:3, why:"Jesus said, He it is, to whom I shall give a sop, when I have dipped it; and He gave it to Judas, who then went out, and it was night." },
      { q:"How did Jesus answer Peter's refusal to have his feet washed?", choices:["Peter could wash Him instead","The others should leave the room","If I wash thee not, thou hast no part with me","Washing was optional symbolism"], a:2, why:"When Peter protested, Thou shalt never wash my feet, Jesus answered, If I wash thee not, thou hast no part with me, and Peter then asked for hands and head." },
      { q:"What does Jesus' washing of feet model for those who follow Him?", choices:["Ceremony matters more than service","Since Lord and Master served, disciples ought to serve one another in humility","Leaders are exempt from such tasks","Service should replace teaching"], a:1, why:"If I then, your Lord and Master, have washed your feet, He said, ye also ought to wash one another's feet; I have given you an example." }
    ] },
  { n:14, summary:"With Judas gone, Jesus spoke comfort to the remaining eleven: let not your heart be troubled; in my Father's house are many mansions, and I go to prepare a place for you, promising to come again and receive you. To Thomas He declared, I am the way, the truth, and the life: no man cometh unto the Father, but by me; to see Him, Philip learned, is to see the Father. Those who believe would do His works and receive whatsoever they asked in His name. The promise at the chapter's heart is another Comforter, the Spirit of truth, the Holy Ghost, whom the Father would send to abide forever, teaching all things and bringing Christ's words to remembrance; Jesus would not leave them comfortless. He left them His peace, urged love shown by keeping His commandments, and said, Arise, let us go hence.",
    context:"On the evening before His crucifixion, with Judas gone out, Jesus comforts the eleven in Jerusalem with promises of a prepared place and the coming Comforter.",
    keyVerses:[
      { ref:"John 14:2", text:"In my Father's house are many mansions: if it were not so, I would have told you. I go to prepare a place for you." },
      { ref:"John 14:6", text:"Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me." },
      { ref:"John 14:26", text:"But the Comforter, which is the Holy Ghost, whom the Father will send in my name, he shall teach you all things, and bring all things to your remembrance, whatsoever I have said unto you." }
    ],
    takeaway:"The Father sends the Comforter, the Holy Ghost, to abide with disciples who love Christ and keep His commandments.",
    quiz:[
      { q:"Which disciple asked, Lord, we know not whither thou goest; and how can we know the way?", choices:["Thomas","Philip","Peter","Judas, not Iscariot"], a:0, why:"Thomas said it, drawing the answer, I am the way, the truth, and the life: no man cometh unto the Father, but by me." },
      { q:"Who is the other Comforter the Father would send in Jesus' name?", choices:["Elias the prophet","An angel of the temple","John the Baptist","The Spirit of truth, the Holy Ghost"], a:3, why:"Jesus said the Father would give another Comforter, even the Spirit of truth, and later named Him plainly: the Comforter, which is the Holy Ghost." },
      { q:"How does Jesus tie love for Him to daily living?", choices:["Love makes commandments unnecessary","If ye love me, keep my commandments","Obedience without feeling suffices","Only sacrifices show love"], a:1, why:"He that hath my commandments, and keepeth them, he it is that loveth me, Jesus said, and such are loved of the Father." }
    ] },
  { n:15, summary:"Jesus called Himself the true vine, His Father the husbandman, and His disciples the branches. Branches that bear no fruit are taken away; fruitful branches are purged to bring forth more fruit, and apart from Him they can do nothing, so they must abide in Him and let His words abide in them. Keeping His commandments is how they continue in His love, and His chief commandment is that they love one another as He loved them, the greatest love laying down life for friends; He now called them servants no longer but friends, chosen and ordained to bring forth fruit that remains. He warned that a world that hated Him would hate them too, remembering the servant is not greater than his lord. The Comforter, the Spirit of truth, would testify of Him, and they would bear witness also.",
    context:"Continuing the same evening's teaching after the Passover supper, before crossing the brook Cedron, Jesus teaches union with Him through the vine and branches.",
    keyVerses:[
      { ref:"John 15:5", text:"I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing." },
      { ref:"John 15:13", text:"Greater love hath no man than this, that a man lay down his life for his friends." },
      { ref:"John 15:16", text:"Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you." }
    ],
    takeaway:"Abiding in Christ is the only source of spiritual fruit, and loving one another as He loved us is His commandment.",
    quiz:[
      { q:"In the vine and branches figure, who is the husbandman?", choices:["The branch","The disciples","The Father","The porter"], a:2, why:"I am the true vine, Jesus said, and my Father is the husbandman, who purges the fruitful branch that it may bring forth more fruit." },
      { q:"What happens to a branch that does not abide in the vine?", choices:["It withers, is gathered, and is burned","It grafts itself into another vine","It bears wild fruit","It becomes a new vine"], a:0, why:"If a man abide not in me, he is cast forth as a branch, and is withered; and men gather them, and cast them into the fire." },
      { q:"What does without me ye can do nothing teach about bearing fruit?", choices:["Diligent effort alone ensures fruit","Fruit-bearing is optional for disciples","Vines symbolize prosperity","All spiritual fruit depends on abiding in Christ"], a:3, why:"As the branch cannot bear fruit of itself except it abide in the vine, no more can ye, except ye abide in me, Jesus said." }
    ] },
  { n:16, summary:"Jesus warned the Twelve that they would be put out of the synagogues and even killed by those who thought they served God. His departure was for their good: unless He went away, the Comforter would not come; when the Spirit of truth came, He would reprove the world of sin, righteousness, and judgment, guide the disciples into all truth, show them things to come, and glorify Christ. A little while, He said, they would not see Him, and a little while again they would, as a travailing woman's sorrow turns to joy; their weeping, while the world rejoiced, would become joy no man could take away. From then they would ask the Father in His name and receive, that their joy might be full. He closed with a promise they would need within hours: in the world ye shall have tribulation; but be of good cheer; I have overcome the world.",
    context:"In His final words before the arrest, Jesus tells the Twelve of coming persecution, the Spirit of truth, sorrow turning to joy, and peace in Him.",
    keyVerses:[
      { ref:"John 16:7", text:"Nevertheless I tell you the truth; It is expedient for you that I go away: for if I go not away, the Comforter will not come unto you; but if I depart, I will send him unto you." },
      { ref:"John 16:13", text:"Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, that shall he speak: and he will shew you things to come." },
      { ref:"John 16:33", text:"These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world." }
    ],
    takeaway:"In tribulation the disciple's peace is Christ Himself, who has overcome the world and sends the Spirit to guide into truth.",
    quiz:[
      { q:"What everyday experience did Jesus use to picture the disciples' sorrow turning to joy?", choices:["A harvest after planting","A woman in travail whose anguish gives way to joy at the child's birth","A storm that passes","A coin that is found"], a:1, why:"A woman in travail hath sorrow, He said, but as soon as she is delivered of the child, she remembereth no more the anguish, for joy." },
      { q:"Why did Jesus tell the Twelve it was expedient for them that He go away?", choices:["To escape the chief priests","Because His work in Galilee was done","Because if He went not away, the Comforter would not come unto them","So they could lead themselves"], a:2, why:"It is expedient for you that I go away, He said; but if I depart, I will send him unto you, the Spirit of truth." },
      { q:"What peace does Jesus leave His disciples in a world of tribulation?", choices:["Peace in Him, who has overcome the world","Freedom from every trial","Withdrawal from the world","Silence about suffering"], a:0, why:"In the world ye shall have tribulation: but be of good cheer; I have overcome the world, He promised on the night of His arrest." }
    ] },
  { n:17, summary:"After teaching, Jesus lifted His eyes to heaven and prayed, the hour being come: Father, glorify thy Son. He had finished the work given Him on earth and had manifested the Father's name to the men the Father gave Him out of the world, who had kept His word and believed He came from God. He prayed for them, not for the world: keep them in the Father's name, keep them from the evil, and sanctify them through truth, for as the Father sent Him into the world, so He sent them; none had been lost but the son of perdition. He prayed also for everyone who would believe through their word, that all may be one, as the Father is in Him and He in the Father, and that they might be with Him to behold His glory, loved as the Son is loved.",
    context:"Closing the evening before His arrest, Jesus prays aloud to the Father for His disciples and for all who would believe on Him through their word.",
    keyVerses:[
      { ref:"John 17:3", text:"And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent." },
      { ref:"John 17:17", text:"Sanctify them through thy truth: thy word is truth." },
      { ref:"John 17:21", text:"That they all may be one; as thou, Father, art in me, and I in thee, that they also may be one in us: that the world may believe that thou hast sent me." }
    ],
    takeaway:"Eternal life is knowing the only true God and Jesus Christ; unity among believers declares to the world that the Father sent the Son.",
    quiz:[
      { q:"For whom did Jesus pray in this chapter?", choices:["Only for Himself","For the Roman rulers alone","For Israel's armies","For His disciples, and for all who would believe on Him through their word"], a:3, why:"Neither pray I for these alone, He said, but for them also which shall believe on me through their word." },
      { q:"How did Jesus define life eternal in His prayer?", choices:["Unbroken rest from labor","Knowing thee the only true God, and Jesus Christ, whom thou hast sent","Possessing the land","Yearly worship at the temple"], a:1, why:"And this is life eternal, He prayed, that they might know thee the only true God, and Jesus Christ, whom thou hast sent." },
      { q:"What did Jesus ask the Father to accomplish through the oneness of believers?", choices:["Their wealth and safety","Rome's conversion","That the world may believe that thou hast sent me","The rebuilding of the temple"], a:2, why:"That they all may be one; as thou, Father, art in me, and I in thee, He prayed, that the world may believe that thou hast sent me." }
    ] },
  { n:18, summary:"Jesus crossed the brook Cedron with His disciples into a garden, where Judas arrived with a band of men and officers carrying lanterns, torches, and weapons. When Jesus answered, I am he, the armed party went backward and fell to the ground; He secured His disciples' release and checked Peter, who had cut off Malchus's ear: the cup which my Father hath given me, shall I not drink it? Bound and led first to Annas, then to Caiaphas, Jesus was struck by an officer for His answer, while Peter, warming himself at the fire, denied Him three times before the cock crew. Before Pilate in the judgment hall, Jesus testified that His kingdom was not of this world and that He came to bear witness unto the truth. Pilate found no fault in Him and offered to release the King of the Jews; the crowd chose the robber Barabbas instead.",
    context:"After crossing the brook Cedron to a garden, Jesus is seized and taken to Annas and Caiaphas while Peter denies Him; Pilate questions Him in the hall of judgment.",
    keyVerses:[
      { ref:"John 18:11", text:"Then said Jesus unto Peter, Put up thy sword into the sheath: the cup which my Father hath given me, shall I not drink it?" },
      { ref:"John 18:36", text:"Jesus answered, My kingdom is not of this world: if my kingdom were of this world, then would my servants fight, that I should not be delivered to the Jews: but now is my kingdom not from hence." },
      { ref:"John 18:37", text:"Pilate therefore said unto him, Art thou a king then? Jesus answered, Thou sayest that I am a king. To this end was I born, and for this cause came I into the world, that I should bear witness unto the truth. Every one that is of the truth heareth my voice." }
    ],
    takeaway:"Christ's kingdom is not of this world; He yielded to the Father's cup, and no earthly power could hold Him except by heaven's allowance.",
    quiz:[
      { q:"Whose right ear did Peter cut off with a sword in the garden?", choices:["Malchus, the high priest's servant","Annas","Barabbas","The captain of the band"], a:0, why:"Simon Peter drew a sword and smote the high priest's servant, cutting off his right ear; the servant's name was Malchus." },
      { q:"What happened when Jesus told the armed band, I am he?", choices:["They laughed at Him","They arrested Peter instead","They went backward and fell to the ground","They withdrew to the city"], a:2, why:"As soon then as he had said unto them, I am he, they went backward, and fell to the ground." },
      { q:"What did Jesus' answer to Pilate reveal about His kingdom?", choices:["It would be won by the sword","It existed only in symbol","His servants would soon fight for Jerusalem","My kingdom is not of this world, so His servants did not fight to prevent His being delivered"], a:3, why:"If my kingdom were of this world, then would my servants fight, Jesus said; but now is my kingdom not from hence." }
    ] },
  { n:19, summary:"Pilate scourged Jesus, and the soldiers crowned Him with thorns and robed Him in purple, mocking, Hail, King of the Jews. Pilate repeatedly declared he found no fault in Him, but when the chief priests cried that by their law He must die for making Himself the Son of God, and threatened, If thou let this man go, thou art not Caesar's friend, Pilate delivered Him to be crucified. Jesus carried His cross to Golgotha, the place of a skull, and was crucified between two others under a title Pilate would not change: JESUS OF NAZARETH THE KING OF THE JEWS. At the cross He gave His mother into the care of the disciple whom He loved, then said, It is finished, and gave up the ghost. A soldier pierced His side, bringing forth blood and water, an eyewitness record; Joseph of Arimathaea and Nicodemus laid Him in a new sepulchre.",
    context:"At the Passover preparation in Jerusalem, Pilate delivers Jesus to be crucified at Golgotha; He dies there, and Joseph of Arimathaea and Nicodemus bury Him in a new sepulchre in a garden.",
    keyVerses:[
      { ref:"John 19:26", text:"When Jesus therefore saw his mother, and the disciple standing by, whom he loved, he saith unto his mother, Woman, behold thy son!" },
      { ref:"John 19:30", text:"When Jesus therefore had received the vinegar, he said, It is finished: and he bowed his head, and gave up the ghost." },
      { ref:"John 19:34", text:"But one of the soldiers with a spear pierced his side, and forthwith came there out blood and water." }
    ],
    takeaway:"Jesus finished the work His Father gave Him, laying down His life of Himself; the eyewitness record stands that we might believe.",
    quiz:[
      { q:"What title did Pilate write and place on the cross?", choices:["Jesus the Nazarene","JESUS OF NAZARETH THE KING OF THE JEWS","This is Jesus the prophet","The Son of God condemned"], a:1, why:"The writing was, JESUS OF NAZARETH THE KING OF THE JEWS, in Hebrew, and Greek, and Latin, and Pilate refused to alter it: What I have written I have written." },
      { q:"Why did the soldiers not break Jesus' legs on the cross?", choices:["Pilate forbade them","The crowd prevented it","Nightfall interrupted them","He was dead already, fulfilling the scripture that a bone of him shall not be broken"], a:3, why:"Coming to Jesus, the soldiers saw He was dead already; John ties this to the scripture, A bone of him shall not be broken." },
      { q:"What did the disciple who saw blood and water flow from Jesus' side intend by recording it?", choices:["That readers might believe, for his record is true","To describe Roman methods","To accuse the soldiers","To comfort the soldiers"], a:0, why:"And he that saw it bare record, and his record is true: and he knoweth that he saith true, that ye might believe." }
    ] },
  { n:20, summary:"On the first day of the week, while it was yet dark, Mary Magdalene found the stone taken away and ran to tell Peter and the disciple whom Jesus loved. They found the sepulchre empty, the linen clothes lying and the napkin wrapped together in a place by itself, and that disciple saw and believed. Weeping, Mary met the risen Lord, at first taking Him for the gardener, until He spoke her name and she announced to the disciples, I have seen the Lord. That evening, doors shut for fear of the Jews, Jesus stood among them saying, Peace be unto you, showed His hands and His side, commissioned them as the Father had sent Him, and breathed on them, Receive ye the Holy Ghost. Eight days later Thomas, who had demanded proof, confessed, My Lord and my God. The book's purpose follows: that ye might believe.",
    context:"On the first day of the week near Jerusalem, the tomb is found empty; the risen Jesus appears to Mary Magdalene, to the disciples that evening, and eight days later to Thomas.",
    keyVerses:[
      { ref:"John 20:28", text:"And Thomas answered and said unto him, My Lord and my God." },
      { ref:"John 20:29", text:"Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed." },
      { ref:"John 20:31", text:"But these are written, that ye might believe that Jesus is the Christ, the Son of God; and that believing ye might have life through his name." }
    ],
    takeaway:"Blessed are they that have not seen, and yet have believed; the written witness of the risen Christ is meant to bring us that life.",
    quiz:[
      { q:"Which disciple outran Peter and reached the sepulchre first?", choices:["Thomas Didymus","Andrew","The other disciple, whom Jesus loved","Philip"], a:2, why:"They ran both together: and the other disciple did outrun Peter, and came first to the sepulchre; that disciple is the one whom Jesus loved." },
      { q:"What did Thomas say when he saw the risen Lord?", choices:["My Lord and my God","It is the Lord","Rabboni; which is to say, Master","Hosanna in the highest"], a:0, why:"Thomas answered and said unto him, My Lord and my God, after being invited to touch His hands and side." },
      { q:"What blessing did Jesus pronounce on those who believe without seeing?", choices:["They will never face doubt","Blessed are they that have not seen, and yet have believed","They will receive any sign they ask","They escape all tribulation"], a:1, why:"Thomas, because thou hast seen me, thou hast believed, Jesus said: blessed are they that have not seen, and yet have believed." }
    ] },
  { n:21, summary:"Jesus showed Himself again to His disciples at the sea of Tiberias. Seven went fishing with Peter and caught nothing all night; at dawn a figure on the shore told them to cast their net on the right side, and the haul was so great they could not draw it. The disciple whom Jesus loved recognized, It is the Lord, and Peter swam ashore to find coals of fire, fish, and bread, and to hear the count: an hundred and fifty and three fishes, the net unbroken. After they dined, Jesus asked Simon Peter three times, Lovest thou me? and three times commissioned him: Feed my lambs; feed my sheep. He foretold the death by which Peter would glorify God and said, Follow me. When Peter asked what John would do, Jesus answered, If I will that he tarry till I come, what is that to thee? The disciple testifying these things wrote them, and the world could not contain the books if all were told.",
    context:"By the sea of Tiberias in Galilee, the risen Jesus appears to seven disciples at dawn, restores Peter with a threefold commission, and speaks of Peter's and John's futures.",
    keyVerses:[
      { ref:"John 21:15", text:"So when they had dined, Jesus saith to Simon Peter, Simon, son of Jonas, lovest thou me more than these? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my lambs." },
      { ref:"John 21:22", text:"Jesus saith unto him, If I will that he tarry till I come, what is that to thee? follow thou me." },
      { ref:"John 21:25", text:"And there are also many other things which Jesus did, the which, if they should be written every one, I suppose that even the world itself could not contain the books that should be written. Amen." }
    ],
    takeaway:"Love for the Lord proves itself in feeding His sheep, and every disciple's part is simply to follow Him.",
    quiz:[
      { q:"How many fishes did the disciples' net hold after the Lord's instruction?", choices:["Forty","Three score and ten","Seven","An hundred and fifty and three"], a:3, why:"Simon Peter drew the net to land full of great fishes, an hundred and fifty and three: and for all there were so many, yet was not the net broken." },
      { q:"What was the effect of Jesus asking Peter three times, Lovest thou me?", choices:["It exposed Peter publicly","It tested Peter's memory of the catch","It gave Peter a threefold affirmation of love, each answered with a commission: Feed my lambs; feed my sheep","It settled who would lead the fishing crews"], a:2, why:"Three times Peter affirmed his love, and three times the Lord charged him to feed His lambs and sheep, restoring him to service." },
      { q:"When Peter asked what would become of John, how did Jesus answer?", choices:["If I will that he tarry till I come, what is that to thee? follow thou me","John shall not die","You will serve together always","That is not for you to know"], a:0, why:"Jesus redirected Peter from comparing callings: If I will that he tarry till I come, what is that to thee? follow thou me. The saying then spread that that disciple should not die." }
    ] }
);
